import test from 'node:test';
import assert from 'node:assert/strict';
import { roundCents, formatEuros, parseEuros, RATES, convert, formatMoney } from '../src/money.js';

test('roundCents rounds half to even', () => {
  assert.equal(roundCents(124.5), 124);
  assert.equal(roundCents(125.5), 126);
  assert.equal(roundCents(2.4), 2);
  assert.equal(roundCents(2.6), 3);
  assert.equal(roundCents(-0.5), 0);
});

test('roundCents ignores binary noise', () => {
  assert.equal(roundCents(0.1 * 3 * 100), 30);
  assert.equal(roundCents(1.005 * 100), 100);
});

test('formatEuros adds the sign, thousands separators and two decimals', () => {
  assert.equal(formatEuros(123456), '€1,234.56');
  assert.equal(formatEuros(5), '€0.05');
  assert.equal(formatEuros(-250), '-€2.50');
  assert.equal(formatEuros(100000000), '€1,000,000.00');
});

test('parseEuros reads what people type', () => {
  assert.deepEqual(parseEuros('12'), { ok: true, value: 1200 });
  assert.deepEqual(parseEuros('12.5'), { ok: true, value: 1250 });
  assert.deepEqual(parseEuros('1,234.56'), { ok: true, value: 123456 });
  assert.deepEqual(parseEuros('12.345'), { ok: false, error: 'AMOUNT_INVALID' });
  assert.deepEqual(parseEuros('abc'), { ok: false, error: 'AMOUNT_INVALID' });
});

test('RATES has correct values', () => {
  assert.equal(RATES.EUR, 1);
  assert.equal(RATES.USD, 1.085);
  assert.equal(RATES.GBP, 0.8425);
});

test('convert EUR to USD', () => {
  const result = convert(100000, 'USD');
  assert.equal(result.ok, true);
  assert.equal(result.value, 108500);
});

test('convert EUR to GBP', () => {
  const result = convert(100000, 'GBP');
  assert.equal(result.ok, true);
  assert.equal(result.value, 84250);
});

test('convert EUR to EUR is identity', () => {
  const result = convert(123456, 'EUR');
  assert.equal(result.ok, true);
  assert.equal(result.value, 123456);
});

test('convert unknown currency returns error', () => {
  const result = convert(100000, 'JPY');
  assert.equal(result.ok, false);
  assert.equal(result.error, 'UNKNOWN_CURRENCY');
});

test('convert rounds to nearest cent', () => {
  const result = convert(1, 'USD');
  assert.equal(result.ok, true);
  assert.equal(result.value, 1);
});

test('convert negative amount', () => {
  const result = convert(-100000, 'USD');
  assert.equal(result.ok, true);
  assert.equal(result.value, -108500);
});

test('convert zero', () => {
  const result = convert(0, 'USD');
  assert.equal(result.ok, true);
  assert.equal(result.value, 0);
});

test('convert large amount', () => {
  const result = convert(1000000000, 'USD');
  assert.equal(result.ok, true);
  assert.equal(result.value, 1085000000);
});

test('formatMoney EUR', () => {
  assert.equal(formatMoney(123456, 'EUR'), '€1,234.56');
});

test('formatMoney USD', () => {
  assert.equal(formatMoney(100000, 'USD'), '$1,085.00');
});

test('formatMoney GBP', () => {
  assert.equal(formatMoney(100000, 'GBP'), '£842.50');
});

test('formatMoney USD small amount', () => {
  assert.equal(formatMoney(5, 'USD'), '$0.05');
});

test('formatMoney GBP large amount', () => {
  assert.equal(formatMoney(100000000, 'GBP'), '£842,500.00');
});

test('formatMoney negative EUR', () => {
  assert.equal(formatMoney(-250, 'EUR'), '-€2.50');
});

test('formatMoney negative USD', () => {
  assert.equal(formatMoney(-100000, 'USD'), '-$1,085.00');
});

test('formatMoney negative GBP', () => {
  assert.equal(formatMoney(-100000, 'GBP'), '-£842.50');
});

test('formatMoney zero', () => {
  assert.equal(formatMoney(0, 'EUR'), '€0.00');
  assert.equal(formatMoney(0, 'USD'), '$0.00');
  assert.equal(formatMoney(0, 'GBP'), '£0.00');
});

test('formatMoney unknown currency', () => {
  assert.equal(formatMoney(100000, 'JPY'), '');
});

test('formatMoney with thousands separator USD', () => {
  assert.equal(formatMoney(1234567, 'USD'), '$13,395.05');
});

test('formatMoney with thousands separator GBP', () => {
  assert.equal(formatMoney(1234567, 'GBP'), '£10,401.23');
});

test('formatMoney EUR to USD conversion matches rate', () => {
  const result = convert(100000, 'USD');
  assert.equal(result.ok, true);
  const formatted = formatMoney(100000, 'USD');
  assert.equal(formatted, '$1,085.00');
});

test('formatMoney handles rounding correctly', () => {
  const result = convert(333, 'USD');
  assert.equal(result.ok, true);
  const formatted = formatMoney(333, 'USD');
  assert.ok(formatted.includes('$3.61'));
});

test('convert multiple currencies in sequence', () => {
  const r1 = convert(100000, 'USD');
  const r2 = convert(100000, 'GBP');
  const r3 = convert(100000, 'EUR');
  assert.equal(r1.value, 108500);
  assert.equal(r2.value, 84250);
  assert.equal(r3.value, 100000);
});

test('formatMoney EUR with no decimals', () => {
  assert.equal(formatMoney(12300, 'EUR'), '€123.00');
});

test('formatMoney USD with single decimal', () => {
  assert.equal(formatMoney(10850, 'USD'), '$117.72');
});

test('convert 1 cent EUR to USD', () => {
  const result = convert(1, 'USD');
  assert.equal(result.ok, true);
  assert.equal(result.value, 1);
});

test('convert 1 cent EUR to GBP', () => {
  const result = convert(1, 'GBP');
  assert.equal(result.ok, true);
  assert.equal(result.value, 1);
});

