import { ok, fail } from './result.js';
import { getCustomer, TIER_DISCOUNTS, normalizeId } from './customers.js';
import { getProduct } from './catalogue.js';
import { nextInvoiceNumber } from './numbering.js';
import { roundCents } from './money.js';
import { isValidDate, addDays, lastDayOfMonth } from './dates.js';

/**
 * Create a new invoice.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number, discountPercent?: number }>, terms?: string }} params
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number, discountPercent: number }>, terms: string, dueDate: string } } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines, terms = 'NET30' }) {
  // Normalize and validate customer exists
  const normalizedCustomerId = normalizeId(customerId);
  const customerResult = getCustomer(normalizedCustomerId);
  if (!customerResult.ok) return customerResult;

  // Validate issueDate format and real date
  if (!isValidDate(issueDate)) {
    return fail('DATE_INVALID');
  }

  // Validate and calculate dueDate based on terms
  let dueDate;
  if (terms === 'NET14') {
    dueDate = addDays(issueDate, 14);
  } else if (terms === 'NET30') {
    dueDate = addDays(issueDate, 30);
  } else if (terms === 'EOM') {
    dueDate = lastDayOfMonth(issueDate);
  } else {
    return fail('TERMS_INVALID');
  }

  // Validate lines is not empty
  if (!Array.isArray(lines) || lines.length === 0) {
    return fail('NO_LINES');
  }

  // Validate and enrich each line
  const enrichedLines = [];
  for (const line of lines) {
    // Validate qty
    if (!Number.isInteger(line.qty) || line.qty <= 0) {
      return fail('QTY_INVALID');
    }

    // Determine discountPercent: explicit value wins, otherwise use tier discount
    const discountPercent = line.discountPercent !== undefined ? line.discountPercent : TIER_DISCOUNTS[customerResult.value.tier];
    const discountValidation = validateDiscountPercent(discountPercent);
    if (!discountValidation.ok) return discountValidation;

    // Get product and validate SKU
    const productResult = getProduct(line.sku);
    if (!productResult.ok) return productResult;

    const product = productResult.value;
    enrichedLines.push({
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent,
    });
  }

  return ok({
    customerId: normalizedCustomerId,
    issueDate,
    status: 'draft',
    lines: enrichedLines,
    terms,
    dueDate,
  });
}

/**
 * Calculate the total for a single line: qty times unitPrice.
 * @param {{ qty: number, unitPrice: number }} line
 * @returns {number} Total in cents
 */
export function lineTotal(line) {
  return line.qty * line.unitPrice;
}

/**
 * Calculate the discount for a single line: lineTotal times discountPercent / 100.
 * @param {{ qty: number, unitPrice: number, discountPercent?: number }} line
 * @returns {number} Discount in cents, clamped to 0
 */
export function lineDiscount(line) {
  const total = lineTotal(line);
  const discountPercent = line.discountPercent ?? 0;
  return Math.max(0, (total * discountPercent) / 100);
}

/**
 * Calculate the VAT for a single line: (lineTotal - discount) * vatRate / 100, rounded per line.
 * @param {{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }} line
 * @returns {number} VAT in cents, rounded, clamped to 0
 */
export function lineVat(line) {
  const total = lineTotal(line);
  const discount = lineDiscount(line);
  const amountAfterDiscount = Math.max(0, total - discount);
  const vatRate = line.vatRate ?? 0;
  return Math.max(0, roundCents((amountAfterDiscount * vatRate) / 100));
}

/**
 * Calculate totals for an invoice.
 * @param {{ lines: Array<{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }>, voucher?: { code: string, amount: number } }} invoice
 * @returns {{ subtotal: number, discount: number, vat: number, voucher: number, total: number }} All in cents
 */
export function invoiceTotals(invoice) {
  const subtotal = invoice.lines.reduce((sum, line) => sum + lineTotal(line), 0);
  const discount = invoice.lines.reduce((sum, line) => sum + lineDiscount(line), 0);
  const vat = invoice.lines.reduce((sum, line) => sum + lineVat(line), 0);
  const voucher = invoice.voucher?.amount ?? 0;
  const total = Math.max(0, subtotal - discount + vat - voucher);
  return {
    subtotal,
    discount,
    vat,
    voucher,
    total,
  };
}

/**
 * Add a line to an invoice (or increase qty if SKU already exists).
 * @param {{ status: string, customerId: string, issueDate: string, lines: Array }} invoice
 * @param {{ sku: string, qty: number, discountPercent?: number }} item
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array } } | { ok: false, error: string }}
 */
export function addLine(invoice, { sku, qty, discountPercent }) {
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  // Validate qty
  if (!Number.isInteger(qty) || qty <= 0) {
    return fail('QTY_INVALID');
  }

  // Validate discountPercent if provided
  const finalDiscountPercent = discountPercent ?? 0;
  const discountValidation = validateDiscountPercent(finalDiscountPercent);
  if (!discountValidation.ok) return discountValidation;

  // Get product and validate SKU
  const productResult = getProduct(sku);
  if (!productResult.ok) return productResult;

  const product = productResult.value;

  // Create new lines array with the line added or updated
  const newLines = invoice.lines.map((line) => ({ ...line }));
  const existingIndex = newLines.findIndex((line) => line.sku === sku);

  if (existingIndex >= 0) {
    // Update existing line
    newLines[existingIndex] = {
      ...newLines[existingIndex],
      qty: newLines[existingIndex].qty + qty,
    };
  } else {
    // Add new line
    newLines.push({
      sku,
      name: product.name,
      qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent: finalDiscountPercent,
    });
  }

  return ok({
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    status: invoice.status,
    lines: newLines,
    terms: invoice.terms,
    dueDate: invoice.dueDate,
    voucher: invoice.voucher,
  });
}

/**
 * Remove a line from an invoice.
 * @param {{ status: string, customerId: string, issueDate: string, lines: Array }} invoice
 * @param {string} sku
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array } } | { ok: false, error: string }}
 */
export function removeLine(invoice, sku) {
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  const index = invoice.lines.findIndex((line) => line.sku === sku);

  if (index === -1) {
    return fail('LINE_NOT_FOUND');
  }

  if (invoice.lines.length === 1) {
    return fail('NO_LINES');
  }

  const newLines = invoice.lines.filter((line) => line.sku !== sku);

  return ok({
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    status: invoice.status,
    lines: newLines,
    terms: invoice.terms,
    dueDate: invoice.dueDate,
    voucher: invoice.voucher,
  });
}

/**
 * Issue an invoice (convert from draft to issued and assign a number).
 * @param {{ number?: string, status: string, customerId: string, issueDate: string, lines: Array }} invoice
 * @param {string[]} existingNumbers - Array of invoice numbers already issued
 * @returns {{ ok: true, value: { number: string, customerId: string, issueDate: string, status: string, lines: Array } } | { ok: false, error: string }}
 */
export function issueInvoice(invoice, existingNumbers) {
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);

  return ok({
    number,
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    status: 'issued',
    lines: invoice.lines.map((line) => ({ ...line })),
    terms: invoice.terms,
    dueDate: invoice.dueDate,
    voucher: invoice.voucher,
  });
}

/**
 * Apply a voucher to an invoice.
 * @param {{ status: string, customerId: string, issueDate: string, lines: Array, terms: string, dueDate: string, voucher?: { code: string, amount: number } }} invoice
 * @param {{ code: string, amount: number }} voucher
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array, terms: string, dueDate: string, voucher: { code: string, amount: number } } } | { ok: false, error: string }}
 */
export function applyVoucher(invoice, { code, amount }) {
  // Validate status is 'draft'
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  // Validate no existing voucher
  if (invoice.voucher) {
    return fail('VOUCHER_EXISTS');
  }

  // Validate amount is a positive integer
  if (!Number.isInteger(amount) || amount <= 0) {
    return fail('AMOUNT_INVALID');
  }

  return ok({
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    status: invoice.status,
    lines: invoice.lines.map((line) => ({ ...line })),
    terms: invoice.terms,
    dueDate: invoice.dueDate,
    voucher: { code, amount },
  });
}

function validateDiscountPercent(discountPercent) {
  if (typeof discountPercent !== 'number' || discountPercent < 0 || discountPercent > 100) {
    return fail('DISCOUNT_INVALID');
  }
  return ok(discountPercent);
}

